import {replaceSelection} from '../gollum-editor'

export const Creole = {
  'function-bold': {
    search: /([^\n]+)([\n]*)/gi,
    replace: '**$1**$2',
  },

  'function-italic': {
    search: /([^\n]+)([\n]*)/gi,
    replace: '//$1//$2',
  },

  'function-code': {
    search: /([^\n]+)([\n]*)/gi,
    replace: '{{{$1}}}$2',
  },

  'function-hr': {
    append: '\n\n----\n\n',
  },

  'function-ul': {
    search: /(.+)([\n]?)/gi,
    replace: '* $1$2',
  },

  /* This looks silly but is completely valid Markdown */
  'function-ol': {
    search: /(.+)([\n]?)/gi,
    replace: '# $1$2',
  },

  'function-link': {
    exec: () => replaceSelection('[[url|text]]'),
  },

  'function-image': {
    exec: () => replaceSelection('{{url|alt}}'),
  },
}
